insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, hero_image, hero_image_alt, published_at, created_at, updated_at) values ('8c714280-0e57-55a0-9cc4-a38072d445a1', 'table-mountain-aerial-cableway', 'Table Mountain Aerial Cableway', 'NATURE', 'PUBLISHED', 'Rotating cable car to the top of Table Mountain, with walking paths and views over the city and coast.', 'The Cableway runs from the lower station on Tafelberg Road to the summit plateau, weather permitting. Tickets are valid for 7 days, and online tickets cost less than tickets bought at the ticket office. The Cableway may close at short notice in high wind or poor visibility, so allow a flexible time slot.', 'TABLE_MOUNTAIN', 'Tafelberg Road, Cape Town', 'https://www.tablemountain.net/', 120, 'OPENING_HOURS', true, false, null, null, 'Buy online or via WhatsApp through Webtickets, the official ticketing agency. You may still queue on busy days.', 'VERIFIED', 'Prices: ''Ticket rates applicable from 1 July 2026 - 30 June 2027''. Hours: published seasonal first/last car times. The page showed a live closure for gale-force winds on 3 Oct 2026, which illustrates the weather dependency.', '2026-10-03', 'SL Tours research (official sources)', null, null, now(), now(), now());
