insert into activity_faqs (id, activity_id, question, answer, sort_order) values ('7cd49698-b866-5805-8721-b3b788514fb7', '8c714280-0e57-55a0-9cc4-a38072d445a1', 'What happens if the Cableway closes for wind?', 'The Cableway operates weather permitting. Tickets are valid for 7 days, and unused online tickets can be used on the next open day within that week or refunded online, according to the operator.', 0);
insert into activity_faqs (id, activity_id, question, answer, sort_order) values ('81b4dac0-54a0-5d00-af26-6c7c8cd536c5', '8c714280-0e57-55a0-9cc4-a38072d445a1', 'Do young children pay?', 'Children under 4 travel free. Child prices apply from 4 to 17 years.', 1);
insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, hero_image, hero_image_alt, published_at, created_at, updated_at) values ('7c3de800-5747-5e7e-8949-a53a17a6e2e2', 'kirstenbosch-national-botanical-garden', 'Kirstenbosch National Botanical Garden', 'NATURE', 'PUBLISHED', 'South Africa''s famous botanical garden on the slopes of Table Mountain, with the Tree Canopy Walkway and lawns for picnics.', 'Kirstenbosch is run by the South African National Biodiversity Institute (SANBI). Entry fees depend on residency and age, and cash is no longer accepted. Free parking is available at Gates 1, 2 and 3. The Conservatory has shorter hours than the garden.', 'SOUTHERN_SUBURBS', 'Rhodes Drive, Newlands, Cape Town', 'https://www.sanbi.org/gardens/kirstenbosch/', 150, 'OPENING_HOURS', true, false, null, null, 'Entrance tickets can be bought online at Webtickets or at the gate (card only).', 'VERIFIED', 'Fees are labelled ''Admission/entrance fees 2026-2027'' without exact start and end dates; stored without effective dates and re-verify on SANBI''s next financial year. Garden hours: 08:00-19:00 Sep-Mar, 08:00-18:00 Apr-Aug.', '2026-10-03', 'SL Tours research (official sources)', null, null, now(), now(), now());
