insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, hero_image, hero_image_alt, published_at, created_at, updated_at) values ('34f0771c-8991-5004-a553-ed2f19935d5e', 'cape-point', 'Cape Point (Cape of Good Hope section)', 'NATURE', 'PUBLISHED', 'The dramatic south-western tip of the Cape Peninsula within Table Mountain National Park.', 'Cape Point is part of Table Mountain National Park, managed by SANParks. A daily conservation fee applies per person, paid per vehicle at the gate by card only (the gate is cash-free). Entry and exit times change by month.', 'CAPE_POINT', 'Cape Point, Table Mountain National Park', 'https://www.sanparks.org/parks/table-mountain/', 180, 'OPENING_HOURS', true, false, null, null, 'Pay at the gate by card. One payment per vehicle at Cape Point.', 'VERIFIED', 'Conservation fees verified for 1 Nov 2025 - 31 Oct 2026 only. SANParks had not published 2026/27 daily conservation fees for Cape Point on 3 Oct 2026, so plans dated from 1 Nov 2026 show the fee as not yet verified. Adult = 12+, child = 2-11.', '2026-10-03', 'SL Tours research (official sources)', '/assets/gallery/30.jpg', 'Guide at the Cape of Good Hope sign', now(), now(), now());
