insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, hero_image, hero_image_alt, published_at, created_at, updated_at) values ('831205e2-d91f-57e0-911c-69a057cc93fd', 'robben-island-museum', 'Robben Island Museum tour', 'MUSEUM_HISTORY', 'PUBLISHED', 'Ferry and guided tour of the World Heritage Site where Nelson Mandela and other political prisoners were held.', 'General tours depart from the Nelson Mandela Gateway at the V&A Waterfront and take about 3.5 hours including the ferry trip, depending on the boat. Departures are weather and demand permitting. Prices differ for South Africans and non-South Africans.', 'WATERFRONT', 'Nelson Mandela Gateway, V&A Waterfront, Cape Town', 'https://www.robben-island.org.za/', 210, 'SESSIONS', true, false, null, null, 'Book online through the museum''s booking link.', 'VERIFIED', 'General tour schedule and prices from the Tour Types page. A separate Friday-Sunday ''walking tour experience'' costs R1000/R620 (South African adult/child) and R1400/R820 (non-South African) and is not used for estimates.', '2026-10-03', 'SL Tours research (official sources)', null, null, now(), now(), now());
