insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, hero_image, hero_image_alt, published_at, created_at, updated_at) values ('7771b2f6-853f-57b7-9550-295a98e323b9', 'zeitz-mocaa', 'Zeitz MOCAA', 'ART_CULTURE', 'PUBLISHED', 'Museum of contemporary art from Africa and its diaspora, in a converted grain silo at the V&A Waterfront.', 'Zeitz MOCAA is open daily. Under-18s enter free, and African citizens have free entry every Wednesday. Free one-hour tours run Monday to Friday at 12:30, booked on arrival.', 'WATERFRONT', 'Silo Square, Silo District, V&A Waterfront, Cape Town', 'https://zeitzmocaa.museum/', 120, 'OPENING_HOURS', false, true, null, null, 'Tickets via Webtickets or at the museum.', 'VERIFIED', '''Effective 1 September 2026, our general admission price has been adjusted from R265 to R350 for tickets purchased via Webtickets.''', '2026-10-03', 'SL Tours research (official sources)', null, null, now(), now(), now());
