insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, hero_image, hero_image_alt, published_at, created_at, updated_at) values ('45ed6ee5-014d-55cb-8814-79f2a2bf3e07', 'iziko-south-african-museum', 'Iziko South African Museum', 'MUSEUM_HISTORY', 'PUBLISHED', 'Natural history and cultural history museum in the Company''s Garden, with fossils, marine life and the planetarium nearby.', 'Iziko charges different fees for international and local visitors. South African pensioners and students enter free on Fridays. The museum is closed on Christmas Day and Workers'' Day.', 'CITY_CENTRE', '25 Queen Victoria Street, Gardens, Cape Town', 'https://www.iziko.org.za/museums/south-african-museum/', 120, 'OPENING_HOURS', false, true, null, null, 'Pay at the museum.', 'VERIFIED', 'Iziko states a fee increase effective 1 April 2026. Hours: 09:00-17:00 Monday-Sunday, with ''winter weekend hours'' 08:30-16:00 on Saturdays and Sundays; the winter period is not defined, so weekend times should be confirmed in winter.', '2026-10-03', 'SL Tours research (official sources)', null, null, now(), now(), now());
