insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, hero_image, hero_image_alt, published_at, created_at, updated_at) values ('1866cdbb-529f-556e-8b08-1bd932057e2a', 'castle-of-good-hope', 'Castle of Good Hope', 'MUSEUM_HISTORY', 'PUBLISHED', 'South Africa''s oldest surviving colonial building, a 17th-century pentagonal fort with museums and courtyards.', 'The Castle is open 363 days a year from 09:00 to 16:00. Prices are ''valid until further notice''. The operator''s pages give the last ticket sale as 15:15 on the visitor information page and 15:45 on the home page; plans use the earlier time.', 'CITY_CENTRE', 'Castle and Darling Streets, Cape Town', 'https://castleofgoodhope.co.za/', 90, 'OPENING_HOURS', false, false, null, null, 'Pay at the Castle.', 'VERIFIED', 'Conflicting last-sale times on official pages (15:15 vs 15:45); 15:15 used.', '2026-10-03', 'SL Tours research (official sources)', null, null, now(), now(), now());
