insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, hero_image, hero_image_alt, published_at, created_at, updated_at) values ('9d6b15d9-144a-5951-8ac5-680b089a5833', 'neighbourgoods-market', 'Neighbourgoods Market (Old Biscuit Mill)', 'FOOD_MARKET', 'PUBLISHED', 'Saturday food and design market at the Old Biscuit Mill in Woodstock.', 'The Neighbourgoods Market runs on Saturdays from 09:00 to 15:00. Secure Saturday parking is available at the College of Cape Town opposite the Mill.', 'CITY_CENTRE', 'The Old Biscuit Mill, 373-375 Albert Road, Cape Town', 'https://theoldbiscuitmill.co.za/', 90, 'OPENING_HOURS', false, false, null, null, null, 'NOT_PUBLISHED', 'No entry fee is stated on the official visitor page, so admission is shown as not published. The site gives the Saturday parking fee as R10 on the home page and R20 on the visitor information page; the higher figure is used.', '2026-10-03', 'SL Tours research (official sources)', null, null, now(), now(), now());
