insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, hero_image, hero_image_alt, published_at, created_at, updated_at) values ('f26faa0d-3470-545a-bc72-2b25e0c58291', 'groot-constantia', 'Groot Constantia wine estate', 'WINE', 'PUBLISHED', 'South Africa''s oldest wine-producing estate, with tastings, a Cape Dutch manor house museum and cellar tours.', 'Wine tastings let you choose five wines; you must be 18 or older. Tasting rooms have different hours, and guided or self-guided cellar tours run hourly. Picnic baskets must be reserved 24 hours ahead; outside food is not allowed.', 'CONSTANTIA', 'Constantia, Cape Town', 'https://www.grootconstantia.co.za/', 120, 'OPENING_HOURS', false, false, 18, null, 'Book the wine tasting experience online.', 'NOT_PUBLISHED', 'Tasting prices are not shown outside the online booking flow, so they are not published here. Minimum age 18 applies to wine tasting, not to visiting the estate. No street address on the fetched pages; area only.', '2026-10-03', 'SL Tours research (official sources)', null, null, now(), now(), now());
