insert into activity_faqs (id, activity_id, question, answer, sort_order) values ('54636810-81e2-5bae-9419-3e32b7f41104', 'f26faa0d-3470-545a-bc72-2b25e0c58291', 'Can children come?', 'Children can visit the estate, but wine tasting is for guests aged 18 and over.', 0);
